fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Iterate over the string's char indices in reverse to find the last and the
    // penultimate character without allocating.
    let mut rev_chars = txt.char_indices().rev();

    // Try to get the last character.
    let last_char = match rev_chars.next() {
        Some((_, c)) => c,
        None => return false, // Empty string
    };

    // Check that the last character is an ASCII alphabetic letter.
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Try to get the character immediately before the last.
    match rev_chars.next() {
        Some((_, prev_char)) => prev_char == ' ', // Must be a space
        None => true, // The string has exactly one character
    }
}

